import type { ChartValue } from "@tanstack/charts";
import { formatChartIndex } from "@/registry/erbium/charts/chart";

export const visitors = [
  { desktop: 186, mobile: 80, month: "January" },
  { desktop: 305, mobile: 200, month: "February" },
  { desktop: 237, mobile: 120, month: "March" },
  { desktop: 73, mobile: 190, month: "April" },
  { desktop: 209, mobile: 130, month: "May" },
  { desktop: 214, mobile: 140, month: "June" },
];

export const devices = [
  { key: "desktop", label: "Desktop" },
  { key: "mobile", label: "Mobile" },
] as const;

export const shortMonth = (value: ChartValue) => formatChartIndex(value).slice(0, 3);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { LineChart } from "@/registry/erbium/charts/line-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import TimeExample from "./variants/time";



const meta = {
  component: LineChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Pass one row per x value. `index` names the x field and `indexType` says how to read it: `category` (the default), `number`, or `time` for UTC dates.

```tsx
import { LineChart } from "@/registry/erbium/charts/line-chart";

<LineChart ariaLabel="Visitors by month" data={visitors} index="month" series={devices} />;
```

`curve` is `smooth` by default; use `linear` when each value is a discrete reading and `step` for values that hold until they change. For parts of a whole over time, use a stacked [Area Chart](/docs/charts/area-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof LineChart>;

export default { ...meta, title: "Charts/Line Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  grid: boolean;
  legend: boolean;
  points: boolean;
  tooltip: boolean;
}> = {
  argTypes: {
    axis: { control: "boolean" },
    curve: { control: "inline-radio", options: ["smooth", "linear", "step"] },
    grid: { control: "boolean" },
    legend: { control: "boolean" },
    points: { control: "boolean" },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { LineChart } from "@/registry/erbium/charts/line-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export const defaultProps = {
  axis: true,
  curve: "smooth",
  grid: true,
  legend: true,
  points: false,
  tooltip: true,
} satisfies {
  axis: boolean;
  curve: "smooth" | "linear" | "step";
  grid: boolean;
  legend: boolean;
  points: boolean;
  tooltip: boolean;
};

export default function LineChartPlaygroundExample(
  args: {
    axis: boolean;
    curve: "smooth" | "linear" | "step";
    grid: boolean;
    legend: boolean;
    points: boolean;
    tooltip: boolean;
  } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <LineChart
        ariaLabel="Visitors by month and device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Time: Story = {
  parameters: {
    docs: {
      description: { story: "With `indexType="time"`, the x axis is a UTC time scale and spaces dates by their real distance. `indexFormat` sets the tick and tooltip labels, and `format` sets the values." },
      source: { code: "import { LineChart } from "@/registry/erbium/charts/line-chart";

const start = Date.UTC(2026, 9, 1);
const day = 24 * 60 * 60 * 1000;

const latency = Array.from({ length: 30 }, (_, index) => ({
  date: new Date(start + index * day),
  p50: 120 + Math.round(Math.sin(index / 3) * 18),
  p95: 260 + Math.round(Math.cos(index / 4) * 40),
}));

const dateFormat = new Intl.DateTimeFormat("en", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
});

export default function LineChartTimeExample() {
  return (
    <div className="w-full p-4">
      <LineChart
        ariaLabel="Daily response time, median and 95th percentile"
        data={latency}
        index="date"
        indexType="time"
        indexFormat={(value) => (value instanceof Date ? dateFormat.format(value) : String(value))}
        series={[
          { key: "p50", label: "Median" },
          { key: "p95", label: "95th percentile" },
        ]}
        format={(value) => `${value} ms`}
        initialWidth={640}
      />
    </div>
  );
}
" },
    },
  },
  render: TimeExample,
};

